class Scheduler(object):
    def __init__(self, workflow):
        self.workflow = workflow
        self._pending_tasks = []
        self.running_task_ids = set()

    @property
    def pending_tasks(self):
        return self._pending_tasks

    def _pending_task_ids(self):
        return set(map(lambda task: task.task_id, self.pending_tasks))

    def add_pending_task(self, task):
        self._pending_tasks.append(task)
        self.running_task_ids.add(task.task_id)

    def remove_pending_task(self, task):
        self._pending_tasks.remove(task)
        self.running_task_ids.remove(task.task_id)

